package com.ahope.ds.web.superadmin.crypto.controller;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestMapping;

import com.ahope.ds.common.bean.ParamMap;
import com.ahope.ds.common.exception.LogicException;
import com.ahope.ds.common.extension.annotation.RequestParamMap;
import com.ahope.ds.common.web.controller.CommonController;
import com.ahope.ds.web.superadmin.crypto.service.CryptoService;

import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.Parameter;
import io.swagger.v3.oas.annotations.media.Schema;
import io.swagger.v3.oas.annotations.tags.Tag;

@Tag(name = "SuperAdmin - Crypto", description = "슈퍼관리자 암복호화 API")
@Controller
@RequestMapping("/web/super/admin/crypto")
public class CryptoController extends CommonController {

	@Autowired
	private CryptoService cryptoService;

	/** 위치정보 복호화 */
	@Operation(summary = "위치정보 복호화", description = "암호화된 위치정보 값을 복호화합니다.")
	@Parameter(name = "cryptoContent", description = "암호화된 위치정보 값", required = true, schema = @Schema(type = "string"))
	@PostMapping("/location")
	public String getLocationDecryption(@RequestParamMap(requiredValues = {"cryptoContent"}) ParamMap param, Model model) throws LogicException {
		model.addAllAttributes(cryptoService.getLocationDecryption(param));
		return JSON_VIEW;
	}

	/** 개인정보 복호화 */
	@Operation(summary = "개인정보 복호화", description = "암호화된 개인정보 값을 복호화합니다.")
	@Parameter(name = "cryptoContent", description = "암호화된 개인정보 값", required = true, schema = @Schema(type = "string"))
	@PostMapping("/personal")
	public String getPersonalDecryption(@RequestParamMap(requiredValues = {"cryptoContent"}) ParamMap param, Model model) throws LogicException {
		model.addAllAttributes(cryptoService.getPersonalDecryption(param));
		return JSON_VIEW;
	}

	/** 해시화 */
	@Operation(summary = "해시화", description = "평문 값을 HMAC-SHA256으로 해시화합니다.")
	@Parameter(name = "cryptoContent", description = "해시화할 평문 값", required = true, schema = @Schema(type = "string"))
	@PostMapping("/hash")
	public String getHashResult(@RequestParamMap(requiredValues = {"cryptoContent"}) ParamMap param, Model model) throws LogicException {
		model.addAllAttributes(cryptoService.getHashResult(param));
		return JSON_VIEW;
	}

	/** 가입자 찾기 */
	@Operation(summary = "가입자 찾기", description = "평문 CTN으로 가입자의 clientSeq와 memberSeq를 조회합니다.")
	@Parameter(name = "cryptoContent", description = "평문 CTN (휴대전화번호)", required = true, schema = @Schema(type = "string"))
	@PostMapping("/member")
	public String findMemberByCtn(@RequestParamMap(requiredValues = {"cryptoContent"}) ParamMap param, Model model) throws LogicException {
		model.addAllAttributes(cryptoService.findMemberByCtn(param));
		return JSON_VIEW;
	}

}

