import org.springframework.http.MediaType;

@Tag(name = "ECGI", description = "ECGI 관리 API")
@Controller
@RequestMapping("/web/admin/ecgis")
public class ECGIController extends CommonController {

	@Autowired
	private ECGIService service;

	@Operation(summary = "ECGI 목록 화면", description = "ECGI 목록 화면을 조회합니다.")
	@RequestMapping(value = "", method = RequestMethod.GET)
	public String ecgiListView(@RequestParamMap ParamMap param, Model model) {
		if (CommonUtil.isVulnerability(new String[] {"listLength"}, param)) {
			param.remove("listLength");
		}
		model.addAllAttributes(param);
		return "admin/ecgi/ecgiList";
	}

	@Operation(summary = "ECGI 목록 조회", description = "페이징 처리된 ECGI 목록을 조회합니다.")
	@Parameters({
		@Parameter(name = "start", description = "페이징 시작 위치", example = "0", required = false, schema = @Schema(type = "integer", format = "int32")),
		@Parameter(name = "length", description = "페이지당 표시 개수", example = "10", required = false, schema = @Schema(type = "integer", format = "int32"))
	})
