		param.put("clientSeq", param.getSessionAttribute("loginClientSeq"));
		model.addAllAttributes(service.getEcgiList(param));
		return JSON_VIEW;
	}

	@Operation(summary = "ECGI 엑셀 등록 화면", description = "ECGI 엑셀 업로드 화면을 조회합니다.")
