		if (CommonUtil.isVulnerability(new String[] {"listLength"}, param)) {
			param.remove("listLength");
		}
		model.addAllAttributes(param);
		return "admin/ecgi/ecgiExcel";
	}

	@Operation(summary = "ECGI 엑셀 업로드", description = "엑셀 파일을 업로드하여 ECGI를 일괄 등록합니다.")
	@RequestMapping(value = "/excel", method = RequestMethod.POST, consumes = MediaType.MULTIPART_FORM_DATA_VALUE)
