			, @Parameter(description = "ECGI 엑셀 파일") @RequestParam("ecgiExcelFile") MultipartFile ecgiExcelFile) throws LogicException {
		if (!CommonUtil.excelFileExtCheck(CommonUtil.getFileExt(ecgiExcelFile.getOriginalFilename()))){
			throw new LogicException("VALIDATION_FAIL","003");
		}
		param.put("clientSeq", param.getSessionAttribute("loginClientSeq"));
		param.put("accountSeq", param.getSessionAttribute("loginAccountSeq"));
		model.addAllAttributes(service.createEcgiExcelUpload(param, ecgiExcelFile));
		return JSON_VIEW;
	}

	@Operation(summary = "샘플 파일 다운로드", description = "ECGI 엑셀 업로드용 샘플 파일을 다운로드합니다.")
