	@Parameters({
		@Parameter(name = "location", description = "지역명", example = "서울", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "name", description = "ECGI명", example = "ECGI_01", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "ecgi", description = "ECGI", example = "123456789", required = true, schema = @Schema(type = "string"))
	})
	@RequestMapping(value = "", method = RequestMethod.POST)
	public String createEcgi(@RequestParamMap(requiredValues= {"location","name","ecgi"}) ParamMap param, Model model) throws Exception {
		if (CommonUtil.isVulnerability(new String[] {"location", "name", "ecgi"}, param)) {
			throw new LogicException("VULNERABLE_VALUE", "002");
		}
		param.put("clientSeq", param.getSessionAttribute("loginClientSeq"));
		param.put("accountSeq", param.getSessionAttribute("loginAccountSeq"));
		model.addAllAttributes(service.createEcgi(param));
		return JSON_VIEW;
	}

	@Operation(summary = "ECGI 삭제", description = "선택한 ECGI 정보를 삭제합니다.")
