	})
	@RequestMapping(value = "/{ecgiSeqs}", method = RequestMethod.DELETE)
	public String removeEcgi(@PathVariable("ecgiSeqs") String ecgiSeqs
							, @RequestParamMap ParamMap param
							, Model model) {
		param.put("ecgiSeqs", ecgiSeqs);
		param.put("clientSeq", param.getSessionAttribute("loginClientSeq"));
		model.addAllAttributes(service.removeEcgi(param));
		return JSON_VIEW;
	}

	@Operation(summary = "ECGI 목록 엑셀 다운로드", description = "ECGI 목록을 엑셀 파일로 다운로드합니다.")
