package com.ahope.ds.web.admin.traffic.controller;

import com.ahope.ds.common.bean.ParamMap;
import com.ahope.ds.common.bean.ResultMap;
import com.ahope.ds.common.exception.LogicException;
import com.ahope.ds.common.extension.annotation.History;
import com.ahope.ds.common.extension.annotation.RequestParamMap;
import com.ahope.ds.common.extension.annotation.History.HistoryType;
import com.ahope.ds.common.util.CommonUtil;
import com.ahope.ds.common.web.controller.CommonController;
import com.ahope.ds.web.admin.traffic.service.TrafficService;

import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.Parameter;
import io.swagger.v3.oas.annotations.Parameters;
import io.swagger.v3.oas.annotations.media.Schema;
import io.swagger.v3.oas.annotations.tags.Tag;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestMethod;

@Tag(name = "Traffic", description = "트래픽 통계 API")
@Controller
@RequestMapping("/web/admin/traffic")
public class TrafficController extends CommonController {
    @Autowired
    private TrafficService service;

    private static String CLIENT_SEQ = "clientSeq";
    private static String LOGIN_CLIENT_SEQ = "loginClientSeq";

    @Operation(summary = "가입자 트래픽 현황 화면", description = "가입자 트래픽 현황 화면을 조회합니다.")
    @RequestMapping(value = "", method = RequestMethod.GET)
    public String trafficListView(@RequestParamMap ParamMap param, Model model) {
    	System.out.println("param : " + param);
    	// 트래픽 통계 화면에서 넘어왔을 경우 검색 조건과 세션값을 넣어줘야한다
    	if (!param.getString("clientSeq").isEmpty()) {
    		service.callAdminView(param.getLong("clientSeq"), param);
    	}
        param.put(CLIENT_SEQ, param.getSessionAttribute(LOGIN_CLIENT_SEQ));
        ResultMap result = new ResultMap();
        result.put("searchData", param);
        model.addAllAttributes(result);
        return "admin/traffic/trafficList";
    }

    @Operation(summary = "가입자 트래픽 현황 조회", description = "페이징 처리된 가입자 트래픽 현황을 조회합니다.")
    @Parameters({
        @Parameter(name = "start", description = "페이징 시작 위치", example = "0", required = true, schema = @Schema(type = "integer", format = "int32")),
        @Parameter(name = "length", description = "페이지당 표시할 데이터 개수", example = "10", required = true, schema = @Schema(type = "integer", format = "int32")),
        @Parameter(name = "searchType", description = "검색 유형 (CTN:전화번호)", example = "CTN", schema = @Schema(type = "string")),
        @Parameter(name = "searchValue", description = "검색어", example = "", schema = @Schema(type = "string")),
        @Parameter(name = "searchTrafficType", description = "트래픽 종류 (TOTAL:전체, UPLOAD:업로드, DOWNLOAD:다운로드)", example = "TOTAL", schema = @Schema(type = "string")),
        @Parameter(name = "searchPeriodType", description = "조회 기간 유형 (SEARCH_FOR_MONTH:월별, SEARCH_FOR_DAY:일별)", example = "SEARCH_FOR_MONTH", schema = @Schema(type = "string")),
        @Parameter(name = "searchStartDate", description = "조회 시작일 (yyyyMMdd)", example = "20260301", required = true, schema = @Schema(type = "string")),
        @Parameter(name = "searchEndDate", description = "조회 종료일 (yyyyMMdd)", example = "20260318", required = true, schema = @Schema(type = "string")),
        @Parameter(name = "searchDataType", description = "데이터 타입 (CALCULATE:정산, REAL_TIME:실시간)", example = "CALCULATE", schema = @Schema(type = "string"))
    })
	@History(historyType = HistoryType.PERSONAL_INFO_ACCESS, reqType = "current_situation_member_traffic")
    @RequestMapping(value = "status/ajax", method = RequestMethod.GET)
    public String trafficList(@RequestParamMap ParamMap param, Model model) {
    	param.put(CLIENT_SEQ, param.getSessionAttribute(LOGIN_CLIENT_SEQ));
    	model.addAllAttributes(service.getTrafficList(param));
    	return JSON_VIEW;
    }

	@Operation(summary = "가입자 트래픽 엑셀 다운로드 생성", description = "가입자 트래픽 엑셀 파일 생성을 요청합니다.")
	@Parameters({
		@Parameter(name = "searchType", description = "검색 유형 (CTN:전화번호)", example = "CTN", schema = @Schema(type = "string")),
		@Parameter(name = "searchValue", description = "검색어", example = "", schema = @Schema(type = "string")),
		@Parameter(name = "searchTrafficType", description = "트래픽 종류 (TOTAL:전체, UPLOAD:업로드, DOWNLOAD:다운로드)", example = "TOTAL", schema = @Schema(type = "string")),
		@Parameter(name = "searchPeriodType", description = "조회 기간 유형 (SEARCH_FOR_MONTH:월별, SEARCH_FOR_DAY:일별)", example = "SEARCH_FOR_MONTH", schema = @Schema(type = "string")),
		@Parameter(name = "searchStartDate", description = "조회 시작일 (yyyyMMdd)", example = "20260301", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "searchEndDate", description = "조회 종료일 (yyyyMMdd)", example = "20260331", required = true, schema = @Schema(type = "string")),
		@Parameter(name = "searchDataType", description = "데이터 타입 (CALCULATE:정산, REAL_TIME:실시간)", example = "CALCULATE", schema = @Schema(type = "string")),
		@Parameter(name = "excelReason", description = "엑셀 다운로드 사유", example = "업무용", required = true, schema = @Schema(type = "string"))
	})
	@History(historyType = HistoryType.EXCEL_DOWNLOAD, reqType = "current_situation_member_traffic")
	@RequestMapping(value = "excel/make", method = RequestMethod.POST)
	public String makeTrafficExcel(@RequestParamMap ParamMap param, Model model) throws Exception {
	    if (CommonUtil.isVulnerability(new String[] {"excelReason"}, param)) {
            throw new LogicException("VULNERABLE_VALUE", "002");
        }

	    param.put(CLIENT_SEQ, param.getSessionAttribute(LOGIN_CLIENT_SEQ));
	    model.addAllAttributes(service.makeTrafficExcel(param));
