package com.ahope.ds.blackbox.support;

import static io.restassured.RestAssured.given;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.Map;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

import org.junit.jupiter.api.TestInfo;

import io.restassured.filter.cookie.CookieFilter;
import io.restassured.http.ContentType;

/**
 * Black-Box 통합 테스트 공용 지원 유틸리티.
 *
 * <p>내부 애플리케이션 클래스를 import 하지 않는다. 순수 HTTP(RestAssured) + 직접 JDBC 만 사용한다.
 * 모든 접속 정보는 시스템 프로퍼티로 외부 주입 가능하여 별도 프로젝트로 이식해도 동작한다.</p>
 */
public final class BlackBoxSupport {

    private BlackBoxSupport() {
    }

    public static final String BASE_URL =
            System.getProperty("test.server.url", "http://localhost:8080");
    public static final String WIREMOCK_URL =
            System.getProperty("test.wiremock.url", "http://localhost:9090");

    private static final String DB_URL =
            System.getProperty("test.db.url", "jdbc:mysql://localhost:13306/smart_plant");
    private static final String DB_USER =
            System.getProperty("test.db.user", "smartplant");
    private static final String DB_PASSWORD =
            System.getProperty("test.db.password", "smartplant1234");

    /** 서버 docker-compose 의 HASH_PEPPER 와 동일해야 CTN_HASH 등이 일치한다. */
    private static final String HASH_PEPPER =
            System.getProperty("test.hash.pepper", "test_pepper_value");

    /** 병렬 안전: 매 호출마다 독립 Connection. */
    public static Connection getDbConnection() throws Exception {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }

    /** 메서드명 기반 결정적 고유 ID (재실행 시 동일값). */
    public static String testId(TestInfo info) {
        return String.format("T%09d",
                Math.abs(info.getTestMethod().get().getName().hashCode()) % 1_000_000_000);
    }

    /** testId → 9자리 숫자 seq (실 데이터와 겹치지 않도록 8_000_000_000 오프셋). */
    public static long testSeq(TestInfo info) {
        return 8_000_000_000L
                + (Math.abs(info.getTestMethod().get().getName().hashCode()) % 1_000_000_000L);
    }

    // ---- SQL 실행 ----------------------------------------------------------

    public static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
        try (InputStream is = BlackBoxSupport.class.getClassLoader().getResourceAsStream(resourcePath)) {
            if (is == null) {
                throw new IllegalStateException("SQL resource not found: " + resourcePath);
            }
            String sql = new String(is.readAllBytes(), StandardCharsets.UTF_8);
            for (Map.Entry<String, String> e : params.entrySet()) {
                sql = sql.replace("${" + e.getKey() + "}", e.getValue());
            }
            executeSqlScript(sql);
        } catch (RuntimeException e) {
            throw e;
        } catch (Exception e) {
            throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
        }
    }

    public static void executeSqlScript(String sql) {
        try (Connection conn = getDbConnection(); Statement stmt = conn.createStatement()) {
            StringBuilder current = new StringBuilder();
            for (String rawLine : sql.split("\n")) {
                String line = rawLine.trim();
                if (line.isEmpty() || line.startsWith("--")) {
                    continue;
                }
                current.append(line).append(' ');
                if (line.endsWith(";")) {
                    String stmtSql = current.toString().trim();
                    stmtSql = stmtSql.substring(0, stmtSql.length() - 1);
                    if (!stmtSql.isEmpty()) {
                        stmt.execute(stmtSql);
                    }
                    current.setLength(0);
                }
            }
            String tail = current.toString().trim();
            if (!tail.isEmpty()) {
                stmt.execute(tail);
            }
        } catch (Exception e) {
            throw new RuntimeException("SQL script execution failed", e);
        }
    }

    /** 단일 스칼라 조회(첫 컬럼). 없으면 null. */
    public static String queryScalar(String sql, Object... args) {
        try (Connection conn = getDbConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            for (int i = 0; i < args.length; i++) {
                ps.setObject(i + 1, args[i]);
            }
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    return rs.getString(1);
                }
                return null;
            }
        } catch (Exception e) {
            throw new RuntimeException("queryScalar failed: " + sql, e);
        }
    }

    // ---- 해시 (서버 HashUtil.hmacSha256 과 동일 알고리즘) -------------------

    public static String hmacSha256(String plaintext) {
        if (plaintext == null || plaintext.isEmpty()) {
            return "";
        }
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(HASH_PEPPER.getBytes(StandardCharsets.UTF_8), "HmacSHA256"));
            byte[] hash = mac.doFinal(plaintext.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(hash.length * 2);
            for (byte b : hash) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (Exception e) {
            throw new RuntimeException("hmacSha256 failed", e);
        }
    }

    // ---- 세션 기반 관리자 로그인 (2단계: 1차 id/pw → SMS 인증번호 → 2차) ----

    /**
     * 실제 로그인 플로우로 세션 쿠키를 확보한다. 내부 모킹 없이 순수 HTTP + JDBC 로 처리한다.
     * <ol>
     *   <li>POST /web/login/ajax (id, pw) — 서버가 ACCOUNT_SMS 에 인증번호 저장</li>
     *   <li>JDBC 로 ACCOUNT_SMS.CERTIFICATION_NO 조회</li>
     *   <li>POST /web/login/sms (id, pw, certificationNo) — 세션 확립</li>
     * </ol>
     * 반환된 {@link CookieFilter} 를 이후 요청의 filter 로 사용하면 세션이 유지된다.
     */
    public static CookieFilter loginAdmin(String loginId, String rawPw, long accountSeq) {
        CookieFilter cookies = new CookieFilter();

        given().filter(cookies)
                .baseUri(BASE_URL)
                .header("X-Requested-With", "XMLHttpRequest")
                .contentType(ContentType.URLENC)
                .formParam("id", loginId)
                .formParam("pw", rawPw)
        .when()
                .post("/web/login/ajax")
        .then()
                .statusCode(200);

        String cert = queryScalar(
                "SELECT CERTIFICATION_NO FROM ACCOUNT_SMS WHERE ACCOUNT_SEQ = ?", accountSeq);
        if (cert == null) {
            throw new IllegalStateException("SMS certification number not issued for accountSeq=" + accountSeq);
        }

        given().filter(cookies)
                .baseUri(BASE_URL)
                .header("X-Requested-With", "XMLHttpRequest")
                .contentType(ContentType.URLENC)
                .formParam("id", loginId)
                .formParam("pw", rawPw)
                .formParam("certificationNo", cert)
        .when()
                .post("/web/login/sms")
        .then()
                .statusCode(200);

        return cookies;
    }
}

