package com.ahope.ds.common.interceptor;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import jakarta.servlet.http.HttpSession;

import org.mybatis.spring.SqlSessionTemplate;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.slf4j.MDC;
import org.springframework.beans.factory.NoSuchBeanDefinitionException;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.servlet.HandlerInterceptor;
import org.springframework.web.servlet.ModelAndView;
import org.springframework.web.servlet.i18n.SessionLocaleResolver;

import com.ahope.ds.common.bean.ParamMap;
import com.ahope.ds.common.bean.ResultMap;
import com.ahope.ds.common.constnats.Constants;
import com.ahope.ds.common.constnats.Constants.Authz;
import com.ahope.ds.common.context.DSApplicationContext;
import com.ahope.ds.common.exception.ResourceNotFoundException;
import com.ahope.ds.common.util.CommonUtil;
import com.ahope.ds.web.login.dao.LoginDAO;

import org.springframework.stereotype.Component;

@Component
public class AdminLoginInterceptor implements HandlerInterceptor {

	private static final Logger logger = LoggerFactory.getLogger(AdminLoginInterceptor.class);

	@Autowired
	private LoginDAO dao;

	@Autowired
	SessionLocaleResolver localeResolver;

	@Override
	public boolean preHandle(HttpServletRequest req, HttpServletResponse res, Object handler) throws Exception {

		MDC.put("RID", CommonUtil.getRandomStr());

		String[] ajaxUriList = {"/ajax","/chargeFee/search","/usage/search","/v3/api-docs"};
		boolean ajaxFlag = false;
		HttpSession session = req.getSession();
		for (String ajaxUri : ajaxUriList) {
			if (req.getRequestURI().indexOf(ajaxUri) > 0) {
				ajaxFlag = true;
				break;
			}
		}

		if(CommonUtil.isNull(session.getAttribute("loginAccountSeq"))) {
			//ajax에 대한 요청인데 세션이 만료된 경우
			if(ajaxFlag) {
				res.sendError(401);
			} else {
				res.sendRedirect("/web/login");
			}
			return false;
		} else {
			//로그인 중복 체크
			ParamMap param = new ParamMap();
			param.put("accountSeq", session.getAttribute("loginAccountSeq"));
			param.put("loginToken", session.getAttribute("loginToken"));
			if(!dao.checkLoginToken(param)) {
				session.invalidate();
				if(ajaxFlag) {
					res.sendError(401);
				} else {
					res.sendRedirect("/web/login?duplicateLogin=Y");
				}
				return false;
			}
		}

		long accountSeq = ((Number) session.getAttribute("loginAccountSeq")).longValue();
		ResultMap accountInfo = dao.getAccountInfo(accountSeq);
		String authz = accountInfo.getString("authz");
		String loginId = (String) session.getAttribute("loginId");

		String adminHome = "/web/admin";
		if ((!Authz.SYSTEM.equals(authz) && !Authz.SUPER.equals(authz) && req.getRequestURI().matches(adminHome + "/ecgis(/(excel/)?new)?"))
		        || (!Authz.SYSTEM.equals(authz) && !Authz.SUPER.equals(authz) && req.getRequestURI().matches(adminHome + "/agpss(/(excel/)?new)?"))
				|| (!Authz.SYSTEM.equals(authz) && !Authz.SUPER.equals(authz) && req.getRequestURI().matches(adminHome + "/beacons/(excel/)?new"))
				|| (!Authz.SYSTEM.equals(authz) && !Authz.SUPER.equals(authz) && req.getRequestURI().matches(adminHome + "/quality.*"))
				|| (Authz.DEVICE.equals(authz) && !req.getRequestURI().matches(adminHome + "/devices.*"))
				|| (Authz.CONSULTING.equals(authz) && !req.getRequestURI().matches(adminHome + "/qos.*"))) {
			res.sendError(403);
			return false;
		}

		// 시스템 관리자 외 블랙리스트
		if (!Authz.SYSTEM.equals(authz) &&(
		        req.getRequestURI().equals(adminHome + "/members/excel/make") ||
		        req.getRequestURI().equals(adminHome + "/usage/member/excel/make") ||
		        req.getRequestURI().equals(adminHome + "/quota/members/excel/make") ||
		        req.getRequestURI().equals(adminHome + "/traffic/excel/make")
		        )
		    ) {
		    res.sendError(403);
            return false;
		}

		logger.info("[LoginInterceptor] preHandle, URI: " + req.getRequestURI());
		logger.info("[LoginInterceptor] preHandle, Method: " + req.getMethod());

		String method = req.getMethod();
		if(!"GET".equals(method)) {
			logger.info("[LoginInterceptor] preHandle, Account: #{} {} [{}]", accountSeq, loginId, authz);
		}


		if (req.getRequestURI().matches(adminHome + "/members.*")) {
			// 선택 가입자 인터넷 차단 등록 / 해제
			if("PUT".equals("method")
				&& !Authz.SYSTEM.equals(authz)
				&& !Authz.SUPER.equals(authz)
				&& req.getRequestURI().matches(".*/internet-block")) {
				res.sendError(403);
				return false;
			}

			// PUT: 가입자 수정, 복구, 복구 취소, 기기변경 DELETE: 가입자 삭제
			if ("PUT".equals(method) || "DELETE".equals(method)) {
				if (!Authz.SYSTEM.equals(authz) && !Authz.SUPER.equals(authz) && !Authz.JOIN.equals(authz)) {
					res.sendError(403);
					return false;
				}
			}

			// 가입자 등록, 가입자 엑셀 등록
			if ("POST".equals(method)
				&& (req.getRequestURI().equals(adminHome + "/members/")
				|| req.getRequestURI().equals(adminHome + "/members/excel"))) {
				if (!Authz.SYSTEM.equals(authz) && !Authz.SUPER.equals(authz) && !Authz.JOIN.equals(authz)) {
					res.sendError(403);
					return false;
				}
			}

			// 그룹 관리자의 비허용 고객사 접근 방지
			if (Authz.GROUP.equals(authz)) {
				boolean hasClient = false;
				String loginClientSeq = session.getAttribute("loginClientSeq").toString();
				for (String clientSeq : accountInfo.getString("clients").split(",")) {
					if (clientSeq.equals(loginClientSeq))
						hasClient = true;
				}
				if (!hasClient) {
					res.sendError(403);
					return false;
				}
			}
		}

		// 데이터 관리 메뉴 접근 방지 - 데이터 관리(부가 서비스) 설정이 01이 아니면
		if(req.getRequestURI().matches(adminHome + "/quota.*")
				&& !"01".equals(session.getAttribute("loginQuotaOnOff"))) {
			res.sendError(403);
			return false;
		}

		if (!CommonUtil.isNull(session.getAttribute("expiredPw"))) {
			boolean isExpiredPw = (boolean) session.getAttribute("expiredPw");
			if (isExpiredPw) {
				res.sendRedirect("/web/mypage/password");
				return false;
			}
		}

		// DataSource 유효성 체크
		String sqlSessionTemplate = (String)session.getAttribute(Constants.SQL_SESSION_TEMPLATE_NAME);
		if (!CommonUtil.isNull(sqlSessionTemplate)) {
			try {
				DSApplicationContext.getBean(sqlSessionTemplate, SqlSessionTemplate.class);
			} catch (NoSuchBeanDefinitionException ne) {
				throw new ResourceNotFoundException("NOT_FOUNT_SQL_SESSION_BEAN", "888");
			}
		}

		dao.updateLoginDate(((Number) session.getAttribute("loginAccountSeq")).longValue());

		if (CommonUtil.isNull(session.getAttribute("loginClientSeq"))) {
			session.setAttribute("loginClientSeq", -1);
		}

		session.setAttribute("lang", localeResolver.resolveLocale(req));

		return true;
	}

	@Override
	public void postHandle(HttpServletRequest req, HttpServletResponse res, Object handler, ModelAndView mnv) throws Exception {
		// BFCache 포함 브라우저 캐시 방지 - 뒤로가기 시 서버 재요청 강제
		res.setHeader("Cache-Control", "no-store, no-cache, must-revalidate");
		res.setHeader("Pragma", "no-cache");
		res.setDateHeader("Expires", 0);
		logger.info("[LoginInterceptor] postHandle");
	}

	@Override
	public void afterCompletion(HttpServletRequest req, HttpServletResponse res, Object handler, Exception e) throws Exception {
		logger.info("[LoginInterceptor] afterCompletion");
	}


}
