package com.ahope.ds.common.interceptor;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import jakarta.servlet.http.HttpSession;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.slf4j.MDC;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.servlet.HandlerInterceptor;
import org.springframework.web.servlet.ModelAndView;
import org.springframework.web.servlet.i18n.SessionLocaleResolver;

import com.ahope.ds.common.bean.ParamMap;
import com.ahope.ds.common.constnats.Constants;
import com.ahope.ds.common.constnats.Constants.Authz;
import com.ahope.ds.common.util.CommonUtil;
import com.ahope.ds.web.login.dao.LoginDAO;

import org.springframework.stereotype.Component;

@Component
public class SuperAdminLoginInterceptor implements HandlerInterceptor {

	private static final Logger logger = LoggerFactory.getLogger(SuperAdminLoginInterceptor.class);

	@Autowired
	private LoginDAO dao;

	@Autowired
	SessionLocaleResolver localeResolver;

	@Override
	public boolean preHandle(HttpServletRequest req, HttpServletResponse res, Object handler) throws Exception {

		MDC.put("RID", CommonUtil.getRandomStr());

		String[] ajaxUriList = {"/ajax"};
		boolean ajaxFlag = false;
		for (String ajaxUri : ajaxUriList) {
			if (req.getRequestURI().indexOf("/login") < 0 && req.getRequestURI().indexOf(ajaxUri) > 0) {
				ajaxFlag = true;
				break;
			}
		}

		HttpSession session = req.getSession();
		if(!CommonUtil.isNull(session.getAttribute("loginAccountSeq"))) {
			long accountSeq = ((Number) session.getAttribute("loginAccountSeq")).longValue();
			String authz = dao.getAccountInfo(accountSeq).getString("authz");
			String loginAuthz = (String) session.getAttribute("loginAuthz");
			String loginId = (String) session.getAttribute("loginId");

			if (!authz.equals(loginAuthz)) {
				session.invalidate();
				res.sendRedirect("/web/login");
				return false;
			}

			if(!"GET".equals(req.getMethod())) {
				logger.info("[LoginInterceptor] preHandle, Account: #{} {} [{}]", accountSeq, loginId, authz);
			}

			if (!Authz.SYSTEM.equals(authz) && !Authz.SUPER.equals(authz) && !Authz.CONSULTING.equals(authz) && !Authz.GROUP.equals(authz)) {
				session.invalidate();
				res.sendRedirect("/web/login");
				return false;
			}

			String superHome = "/web/super/admin";
			// 시스템,슈퍼 관리자 외 화이트 리스트
			if (!Authz.SYSTEM.equals(authz) && !Authz.SUPER.equals(authz) 
					&& !req.getRequestURI().equals(superHome)
					&& !req.getRequestURI().equals(superHome + "/clients")
					&& !req.getRequestURI().equals(superHome + "/clients/ajax")
					&& !req.getRequestURI().matches(superHome + "/clients/\\d+/admin")) {
				res.sendError(403);
				return false;
			}

			// 슈퍼 관리자 화이트 리스트
			if (Authz.SUPER.equals(authz) && (
			        !req.getRequestURI().equals(superHome) && 
			        !req.getRequestURI().startsWith(superHome + "/clients") &&
			        !req.getRequestURI().startsWith(superHome + "/traffic") &&
			        !req.getRequestURI().startsWith(superHome + "/solutions") &&
			        !req.getRequestURI().startsWith(superHome + "/client") &&
			        !req.getRequestURI().startsWith(superHome + "/interworking")
			        ) 
			   ) {
			    res.sendError(403);
                return false;
			}

			// 슈퍼 관리자 블랙 리스트
			if (Authz.SUPER.equals(authz) && (
			        // 블랙 리스트
			        req.getRequestURI().equals(superHome + "/clients/excel/make")
			        )
			   ) {
			    res.sendError(403);
                return false;
			}

			//로그인 중복 체크
			ParamMap param = new ParamMap();
			param.put("accountSeq", session.getAttribute("loginAccountSeq"));
			param.put("loginToken", session.getAttribute("loginToken"));
			if(!dao.checkLoginToken(param)) {
				session.invalidate();
				if(ajaxFlag) {
					res.sendError(401);	
				} else {
					res.sendRedirect("/web/login?duplicateLogin=Y");
				}
				return false;

			}
		} else {
			//ajax에 대한 요청인데 세션이 만료된 경우
			if(ajaxFlag) {
				res.sendError(401);
			} else {
				res.sendRedirect("/web/login");
			}
			return false;
		}

		if (!CommonUtil.isNull(session.getAttribute("expiredPw"))) {
			boolean isExpiredPw = (boolean) session.getAttribute("expiredPw");
			if (isExpiredPw) {
				res.sendRedirect("/web/mypage/password");
				return false;
			}
		}

		session.removeAttribute("loginClientSeq");
		session.removeAttribute("loginClientLogoUrl");
		session.removeAttribute(Constants.SQL_SESSION_TEMPLATE_NAME);
		session.removeAttribute(Constants.SQL_TRANSACTION_MANAGER_NAME);

		session.setAttribute("lang", localeResolver.resolveLocale(req));

		dao.updateLoginDate(((Number) session.getAttribute("loginAccountSeq")).longValue());

		return true;
	}

	@Override
	public void postHandle(HttpServletRequest req, HttpServletResponse res, Object handler, ModelAndView mnv) throws Exception {
		// BFCache 포함 브라우저 캐시 방지 - 뒤로가기 시 서버 재요청 강제
		res.setHeader("Cache-Control", "no-store, no-cache, must-revalidate");
		res.setHeader("Pragma", "no-cache");
		res.setDateHeader("Expires", 0);
		logger.info("[LoginInterceptor] postHandle");
	}

	@Override
	public void afterCompletion(HttpServletRequest req, HttpServletResponse res, Object handler, Exception e) throws Exception {
		logger.info("[LoginInterceptor] afterCompletion");
	}

}
