package com.ahope.ds.blackbox;

import static com.ahope.ds.blackbox.support.BlackBoxSupport.BASE_URL;
import static com.ahope.ds.blackbox.support.BlackBoxSupport.executeSqlTemplate;
import static com.ahope.ds.blackbox.support.BlackBoxSupport.testId;
import static com.ahope.ds.blackbox.support.BlackBoxSupport.testSeq;
import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;


/**
 * Black-Box API Integration Test (template-rendered)
 *
 * @target-controller ClientAPIController (src/main/java/com/ahope/ds/client/controller/ClientAPIController.java)
 * @target-api GET /client/sync
 *
 * 인증: ClientLoginInterceptor 가 Authorization: Bearer <KMS암호화토큰> 을 요구. 토큰 위조는 블랙박스에서 불가하므로 토큰 거부 경로만 검증한다.
 * 응답: 인터셉터 LogicException 은 CommonClientController @ExceptionHandler(HttpStatus.OK) 로 처리되어 HTTP 200 + ClientResultMap(code/message).
 * err: 816=MISSING_TOKEN, 812=INVALID_TOKEN. 정상 동기화(code 000)는 유효 토큰이 필요해 재현 불가.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class ClientSyncBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        return Map.of(
                "BADTOKEN", "Bearer not-a-real-token",
                "BASICAUTH", "Basic dXNlcjpwYXNz");
    }

    private void arrange(Map<String, String> p) {
        executeSqlTemplate("sql/client-sync-teardown.sql", p);
        executeSqlTemplate("sql/client-sync-setup.sql", p);
    }

    @Test
    void VTC_sync_missingAuthorization(TestInfo info) {
        // Authorization 헤더 누락 → 816
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .header("X-Manufacturer", "samsung")
                    .header("X-Model", "SM-G998N")
                    .header("X-OS-Version", "14")
                    .header("X-App-Version", "02.00.01")
                    .header("X-Requested-With", "XMLHttpRequest")
            .when()
                    .get("/client/sync")
            .then()
                    .statusCode(200)
                    .body("code", equalTo("816"));
        } finally {
            executeSqlTemplate("sql/client-sync-teardown.sql", p);
        }
    }

    @Test
    void VTC_sync_nonBearerAuthorization(TestInfo info) {
