	public ResultMap makeExcel(ParamMap param) throws Exception {
        ResultMap result = new ResultMap();
        String searchType = param.getString("searchType");
        String searchValue = param.getString("searchValue");
        if ("CTN".equals(searchType)) {
            if (searchValue != null && !searchValue.equals("")) {
                param.put("searchValue", hashUtil.hmacSha256(searchValue));
            }
        } else {
            param.put("searchValue", URLDecoder.decode(searchValue, "UTF-8"));
